const M: u32 = crate::field::M; // 2^23 - 2^13 + 1, Dilithium2's modulus
pub const N: usize = 256;
pub const K: usize = 4;
const TAU: usize = 39; //The actual number of swaps gets rounded up to 40 which is fine for security
const S_BALL_END: usize = TAU/HASH_CYCLE_LEN + 2 + 1; //Spending 6 HASH_CYCLES on BALLSAMPLE, +1 for SBALLSTART
const BETA: u32 = 80;
const GAMMA1: u32 = crate::field::GAMMA1; // 2^17
/// Largest `|z|` FIPS 204 admits: `|z| < GAMMA1 - BETA`, so the bound itself is one less.
const Z_LIMIT: u32 = GAMMA1 - BETA - 1;
/// Trim for the second `z` decomposition, so the two windows intersect in exactly
/// `[-Z_LIMIT, Z_LIMIT]`. Previously the second offset was `BETA`, which left the window at
/// `[-(GAMMA1-BETA), GAMMA1-1]` -- 80 values above the bound that a standard verifier rejects.
const Z_SHIFT: u32 = (1u32 << Z_RANGE) - 1 - 2 * Z_LIMIT;

/// Smallest `k` with `x <= 2^k - 1`: the width a bit-decomposition range proof of a value bounded by
/// `x` needs. Every range width below is derived from `M` and `GAMMA2` through this, because four of
/// them change with the modulus and three of those change silently.
const fn bits_for(x: u32) -> usize {
    let mut k = 0;
    while (1u32 << k) - 1 < x {
        k += 1;
    }
    k
}

/// Distinct high-bit values: `w1 in [0, W_HIGH_BOUND - 1]`. 44 for Dilithium2, was 56 for f23201.
const W_HIGH_BOUND: u32 = (M - 1) / (2 * GAMMA2);
const W_HIGH_SHIFT: u32 = (1u32 << bits_for(W_HIGH_BOUND - 1)) - W_HIGH_BOUND;
// Offset for the w0 range proof. One 17-bit decomposition of `w0 + W_LOW_LIMIT` pins
// `w0` to `[-W_LOW_LIMIT, 2^17 - 1 - W_LOW_LIMIT]`. Decompose's non-special output set is
// `[-(GAMMA2 - 1), GAMMA2]` -- `w0 = -GAMMA2` is carried by the W_BIND (w2) flag instead --
// so the offset must be GAMMA2 - 1 to land on it exactly. This works one-sided only because
// 2*GAMMA2 = 2^17 here; a field where 2*GAMMA2 is not a power of two needs two decompositions.
/// Offset for the w0 range proof. Two shifted decompositions of `w0 + W_LOW_LIMIT` and
/// `w0 + W_LOW_LIMIT + W_LOW_SHIFT` intersect to `[-W_LOW_LIMIT, 2^R - 1 - W_LOW_LIMIT - W_LOW_SHIFT]`.
/// Decompose's non-special output set is `[-(GAMMA2 - 1), GAMMA2]` -- `w0 = -GAMMA2` is carried by the
/// W_BIND (w2) flag instead -- so these land on it exactly.
///
/// Two decompositions rather than one because `2*GAMMA2 = 190464` is not a power of two here. Over
/// f23201 it was `2^17` exactly and one sufficed.
const W_LOW_LIMIT: u32 = GAMMA2 - 1;
const W_LOW_SHIFT: u32 = (1u32 << W_LOW_RANGE) - 2 * GAMMA2;
const GAMMA2: u32 = crate::field::GAMMA2;

const C_SIZE: usize = 24;
const FE_TRIT_SIZE: usize = 11;

const Z_RANGE: usize = bits_for(2 * Z_LIMIT);
/// `q_i = x / (N - TAU + i)` for `x < M`, so at most `(M - 1) / (N - TAU)`.
const Q_RANGE: usize = bits_for((M - 1) / ((N - TAU) as u32));
/// `r_i = x % (N - TAU + i)`, so at most `N - 1`.
const R_RANGE: usize = bits_for(N as u32 - 1);
const W_LOW_RANGE: usize = bits_for(2 * GAMMA2 - 1);
const W_HIGH_RANGE: usize = bits_for(W_HIGH_BOUND - 1);

const C_IND: usize = 0;

//Sample In Ball only
const Q_IND: usize = C_IND + C_SIZE;
const R_IND: usize = Q_IND + HASH_CYCLE_LEN;
const SIGN_IND: usize = R_IND + HASH_CYCLE_LEN;

const Q_RANGE_IND: usize = SIGN_IND + HASH_CYCLE_LEN;
const R_RANGE_IND: usize = Q_RANGE_IND + 2*Q_RANGE;

const SWAP_DEC_FE_IND: usize = R_RANGE_IND + 2*R_RANGE;
const SWAP_DEC_TRIT_IND: usize = SWAP_DEC_FE_IND + C_SIZE;
const SWAP_FE_EQUAL_IND: usize =SWAP_DEC_TRIT_IND + FE_TRIT_SIZE; 

//Asserts moved here to use empty transitions during sample in ball
const SWAP_DEC_ASSERT: usize = SWAP_FE_EQUAL_IND + 1;
const SWAP_DEC_FE_ASSERT: usize = SWAP_DEC_ASSERT + 1;
const SWAP_DEC_TRIT_ASSERT: usize = SWAP_DEC_FE_ASSERT + 1;
const SWAP_C_DEC_ASSERT: usize = SWAP_DEC_TRIT_ASSERT + 1;
const M_COM_ASSERT: usize = SWAP_C_DEC_ASSERT + 1;
const M_BALL_ASSERT: usize = M_COM_ASSERT + HASH_DIGEST_WIDTH;
const Q_ASSERT: usize = M_BALL_ASSERT + HASH_DIGEST_WIDTH;
const R_ASSERT: usize = Q_ASSERT + 2;
const QR_ASSERT: usize = R_ASSERT + 2;

const SWAP_C_TRIT: usize = CTILDE_IND - FE_TRIT_SIZE; 

//PIT only
const C_TRIT_IND: usize = SWAP_C_TRIT;
const W_HIGH_IND: usize = Q_IND; // HASH_RATE_WIDTH wlow per row for first 6 rows. Placing everything at once because we permute
const W_IND: usize = W_HIGH_IND + HASH_RATE_WIDTH; // 4 w per row for first 6 rows
const W_BIND: usize = W_IND + 4; // 4 wbit per row for first 6 rows
const W_LOW_IND: usize = W_BIND + 4; // 4 w per row for first 6 rows
const Z_IND: usize = W_LOW_IND + 4;
const QW_IND: usize = Z_IND + 4;

const Z_RANGE_IND: usize = QW_IND + 4;
const W_LOW_RANGE_IND: usize = Z_RANGE_IND + 8*Z_RANGE;
const W_HIGH_RANGE_IND: usize = W_LOW_RANGE_IND + 8*W_LOW_RANGE;

//All the way
const CTILDE_IND: usize = W_HIGH_RANGE_IND + 8*W_HIGH_RANGE + FE_TRIT_SIZE;

const M_IND: usize = CTILDE_IND + HASH_DIGEST_WIDTH;

const HASH_IND: usize = M_IND + HASH_DIGEST_WIDTH;

// Below show up only in result space
const SWAP_ASSERT: usize = HASH_IND + 3*HASH_STATE_WIDTH + 3*HASH_STATE_WIDTH; //3*HASH_STATE_WIDTH for hashing and double for assertions
const SET_ASSERT: usize = SWAP_ASSERT + 1;
const C_TRIT_ASSERT: usize = SET_ASSERT + 1;
const W_DEC_ASSERT: usize = C_TRIT_ASSERT + 1;
const W_LOW_ASSERT: usize = W_DEC_ASSERT + 2*4;
const W_HIGH_ASSERT: usize = W_LOW_ASSERT + 2*4;
const CTILDE_ASSERT: usize = W_HIGH_ASSERT + 2*4;
const Z_ASSERT: usize = CTILDE_ASSERT + HASH_DIGEST_WIDTH; // 4 w's, each has 3 checks

// The derived constants above, pinned. If a modulus change or a formula slip moves any of them the
// build fails here rather than in a proof six months later. The two window checks are the ones that
// matter: they assert the range proofs land exactly on Decompose's output sets.
const _: () = assert!(M == 8380417);            // 2^23 - 2^13 + 1
const _: () = assert!(GAMMA2 == 95232);         // (M - 1) / 88
const _: () = assert!(Z_LIMIT == 130991);       // GAMMA1 - BETA - 1
const _: () = assert!(Z_SHIFT == 161);
// z must land in exactly [-Z_LIMIT, Z_LIMIT], the standard's |z| < GAMMA1 - BETA.
const _: () = assert!((1u32 << Z_RANGE) - 1 - Z_LIMIT - Z_SHIFT == Z_LIMIT);
const _: () = assert!(Z_RANGE == 18);
const _: () = assert!(Q_RANGE == 16);
const _: () = assert!(R_RANGE == 8);
const _: () = assert!(W_HIGH_BOUND == 44);      // (M - 1) / (2 * GAMMA2); was 56 over f23201
const _: () = assert!(W_HIGH_RANGE == 6);
const _: () = assert!(W_HIGH_SHIFT == 20);      // was 8 over f23201
const _: () = assert!(W_LOW_RANGE == 18);       // was 17 over f23201
const _: () = assert!(W_LOW_LIMIT == 95231);
const _: () = assert!(W_LOW_SHIFT == 71680);

// w1 in [0, 2^R - 1 - W_HIGH_SHIFT] must be exactly [0, W_HIGH_BOUND - 1].
const _: () = assert!((1u32 << W_HIGH_RANGE) - 1 - W_HIGH_SHIFT == W_HIGH_BOUND - 1);
// w0 in [-W_LOW_LIMIT, 2^R - 1 - W_LOW_LIMIT - W_LOW_SHIFT] must be exactly
// [-(GAMMA2 - 1), GAMMA2] -- Decompose's output set minus the -GAMMA2 the w2 flag carries.
const _: () = assert!(W_LOW_LIMIT == GAMMA2 - 1);
const _: () = assert!((1u32 << W_LOW_RANGE) - 1 - W_LOW_LIMIT - W_LOW_SHIFT == GAMMA2);
// The powers-of-two table in air.rs must still cover the widest range proof.
const _: () = assert!(Z_RANGE <= 21 && W_LOW_RANGE <= 21 && Q_RANGE <= 21);
// The base-4 challenge packing needs 4^FE_TRIT_SIZE <= M to stay uniquely decodable.
const _: () = assert!(4u64.pow(FE_TRIT_SIZE as u32) <= M as u64);

pub const TRACE_WIDTH: usize = HASH_IND + 3*HASH_STATE_WIDTH;
pub const AUX_WIDTH: usize = 1 + 4 + 4 + 4 + 1; // C + Z + W + QW + GAMMA(random evaluation point)

pub const S_BALL_START: usize = HASH_CYCLE_LEN;

pub const COM_START: usize = (HASH_CYCLE_LEN)*(S_BALL_END+1);
pub const COM_END: usize = (HASH_CYCLE_LEN)*(S_BALL_END+2);

pub const PIT_START: usize = (HASH_CYCLE_LEN)*(S_BALL_END+3);
pub const PIT_LEN: usize = (N+2)*HASH_CYCLE_LEN/(HASH_CYCLE_LEN-2);
pub const PIT_END: usize = PIT_START+PIT_LEN;

pub const PADDED_TRACE_LENGTH: usize = 512;
pub const _TRACE_LENGTH: usize = PIT_END;

