const HTR: [u32;HASH_STATE_WIDTH] = [2582929, 3598748, 7930133, 4786055, 6863061, 3323073, 4906178, 259422, 4918515, 1481828, 4980318, 3618997, 1446623, 2211196, 1813295, 4576341, 3586010, 483567, 5826019, 4794284, 2382786, 7904814, 2737523, 6975813, 5638370, 5580464, 2403096, 595785, 7663975, 7846716, 8372275, 761229, 4978882, 7782843, 3157020];

pub fn prove(
    z: [[BaseElement; N]; K],
    w: [[BaseElement; N]; K],
    qw: [[BaseElement; N]; K],
    ctilde: [BaseElement; HASH_DIGEST_WIDTH],
    m: [BaseElement; 12],
    comm: [BaseElement; HASH_DIGEST_WIDTH],
    com_r: [BaseElement; 12],
    nonce: [BaseElement; 12]
) -> Proof {
    // 48,4,20
    // 32,8,20
    // 24,16,20
    // 19,32,21
    // 16,64,20
    // 14,128,20
        let options = ProofOptions::new(
            // f23 has two-adicity 13, so trace_length_ext * blowup <= 2^13 = 8192. With
            // zero-knowledge the 512-row trace extends to 1024, so blowup 16 would need 2^14 --
            // unreachable in this field. 32/8 sits exactly at the ceiling (1024 * 8 = 8192) and is
            // the best size/speed balance of the equivalent-security options listed above.
            32, // number of queries
            8,  // blowup factor
            20,  // grinding factor
            FieldExtension::Sextic,
            8,   // FRI folding factor
            127, // FRI max remainder length
            winterfell::BatchingMethod::Linear, //TODO
            winterfell::BatchingMethod::Linear, //TODO
            true,
        );
        debug!(
            "Generating proof for correctness of Merkle tree"
        );

        // create a prover
        let now = Instant::now();
        let prover = ThinDilMulShowProver::new(options.clone(), z, w, qw, ctilde, m, comm, com_r, nonce);

        // generate execution trace
        let trace = prover.build_trace();

        let trace_width = trace.width();
        let trace_length = trace.length();
        debug!(
            "Generated execution trace of {} registers and 2^{} steps in {} ms \n",
            trace_width,
            trace_length.ilog2(),
            now.elapsed().as_millis()
        );

        // generate the proof
        let seed = ChaCha20Rng::from_entropy().get_seed();
        prover.prove(trace, Some(seed)).unwrap()
    }

    pub fn verify(proof: Proof, comm: [BaseElement; HASH_DIGEST_WIDTH], nonce: [BaseElement; 12]) -> Result<(), VerifierError> {
        let pub_inputs = PublicInputs{comm, nonce};
        let acceptable_options =
            winterfell::AcceptableOptions::OptionSet(vec![proof.options().clone()]);

        winterfell::verify::<ThinDilMulShowAir, Blake3_256<BaseElement>, DefaultRandomCoin<Blake3_256<BaseElement>>, MerkleTree<Blake3_256<BaseElement>>>(
            proof,
            pub_inputs,
            &acceptable_options,
        )
    }

    pub fn verify_with_wrong_inputs(proof: Proof, comm: [BaseElement; HASH_DIGEST_WIDTH], nonce: [BaseElement; 12]) -> Result<(), VerifierError> {
        let pub_inputs = PublicInputs{comm, nonce};
        let acceptable_options =
            winterfell::AcceptableOptions::OptionSet(vec![proof.options().clone()]);

        winterfell::verify::<ThinDilMulShowAir, Blake3_256<BaseElement>, DefaultRandomCoin<Blake3_256<BaseElement>>, MerkleTree<Blake3_256<BaseElement>>>(
            proof,
            pub_inputs,
            &acceptable_options,
        )
    }